def cheapest_route(flights, src, dst, max_stops):
    if src == dst:
        return (0, [src])

    adj = {}
    for o, d, p in flights:
        adj.setdefault(o, []).append((d, p))

    # Sort edges by price then destination to find cheaper routes early and keep order deterministic
    for k in adj:
        adj[k].sort(key=lambda x: (x[1], x[0]))

    best = None
    visited = {src}
    path = [src]
    limit = max_stops + 1  # max allowed flights

    def dfs(u, price, flights_count):
        nonlocal best
        if u == dst:
            # Tie-breaking matches tuple comparison: (price, flight_count, airport_list)
            cand = (price, flights_count, list(path))
            if best is None or cand < best:
                best = cand
            return

        # Pruning: edge weights are non-negative. Any path extension will have 
        # total_price >= current price and flight_count > current count.
        # Since we prefer fewer flights for equal price, further exploration cannot beat `best`.
        if best is not None and price >= best[0]:
            return

        if flights_count >= limit:
            return

        for v, p in adj.get(u, []):
            if v not in visited:
                visited.add(v)
                path.append(v)
                dfs(v, price + p, flights_count + 1)
                path.pop()
                visited.remove(v)

    dfs(src, 0, 0)
    return (best[0], best[2]) if best else None
