from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        if ttl <= 0:
            raise ValueError("ttl must be > 0")
        self._capacity = capacity
        self._ttl = ttl
        self._clock = clock
        self._cache = OrderedDict()
        self._expirations = {}

    def _remove(self, key):
        if key in self._cache:
            del self._cache[key]
        self._expirations.pop(key, None)

    def _is_expired(self, key):
        return key in self._expirations and self._clock() >= self._expirations[key]

    def _clean_expired(self):
        for key in list(self._cache.keys()):
            if self._is_expired(key):
                del self._cache[key]
                del self._expirations[key]

    def set(self, key, value):
        now = self._clock()
        expire_at = now + self._ttl

        # Update live entry: reset TTL, mark MRU
        if key in self._cache and not self._is_expired(key):
            self._cache[key] = value
            self._expirations[key] = expire_at
            self._cache.move_to_end(key)
            return

        # Key is missing or expired: remove stale reference first
        if key in self._cache:
            del self._cache[key]
            self._expirations.pop(key, None)

        # Evict LRU live entries only when we are at capacity
        if len(self._cache) >= self._capacity:
            self._clean_expired()
        while len(self._cache) >= self._capacity:
            oldest_key = next(iter(self._cache))
            self._remove(oldest_key)

        self._cache[key] = value
        self._expirations[key] = expire_at

    def get(self, key, default=None):
        if key in self._cache and not self._is_expired(key):
            self._cache.move_to_end(key)  # MRU
            return self._cache[key]
        return default

    def delete(self, key) -> bool:
        if key in self._cache and not self._is_expired(key):
            self._remove(key)
            return True
        return False

    def __len__(self):
        self._clean_expired()
        return len(self._cache)

    def __contains__(self, key) -> bool:
        return key in self._cache and not self._is_expired(key)
