            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i+1] == '"':
                        parts.append('"')
                        i += 2
                    else:
                        i += 1
                        closed = True
                        break
                else:
                    parts.append(line[i])
                    i += 1
            if not closed:
                raise ValueError("Unclosed quoted field")
            fields.append("".join(parts))
            if i < n and line[i] != ',':
                raise ValueError("Closing quote must be followed by comma or end of line")
        else:
            j = line.find(',', i)
            if j == -1:
                fields.append(line[i:])
                return fields
            else:
                fields.append(line[i:j])
                i = j + 1

        if i >= n:
            break
    return fields
