                raise ValueError("a > b")
            res.update(range(a, b + 1))
        else:
            raise ValueError("Malformed item")
    return sorted(res)

def compress_ranges(nums) -> str:
    if not nums:
        return ""
    nums = sorted(set(nums))
    result = []
    start = end = nums[0]
    for num in nums[1:]:
        if num == end + 1:
            end = num
        else:
            if start == end:
                result.append(str(start))
            elif end - start == 1:
                result.extend([str(start), str(end)])
            else:
                result.append(f"{start}-{end}")
            start = end = num
    # Handle last group
    if start == end:
        result.append(str(start))
    elif end - start == 1:
        result.extend([str(start), str(end)])
    else:
        result.append(f"{start}-{end}")
