import heapq

def cheapest_route(flights, src, dst, max_stops):
    if src == dst:
        return (0, [src])

    # Build adjacency list keeping only the cheapest flight per pair
    adj = {}
    for o, d, p in flights:
        if o not in adj:
            adj[o] = {}
        if d not in adj[o] or p < adj[o][d]:
            adj[o][d] = p

    # Min-heap stores tuples of (total_price, flights_taken, route_path)
    # Python tuple comparison naturally implements the tie-breaking rules:
    # 1. cheapest price
    # 2. fewest flights
    # 3. lexicographically smallest airport sequence
    pq = [(0, 0, [src])]
    visited = set()
    max_flights = max_stops + 1

    while pq:
        price, stops, path = heapq.heappop(pq)
        curr = path[-1]

        # First time we reach dst is guaranteed to be optimal due to heap ordering
        if curr == dst:
            return (price, path)

        # Skip already finalized airports (optimal route found for this node)
        if curr in visited:
            continue
        visited.add(curr)

        # Respect maximum flight limit
        if stops >= max_flights:
            continue

        # Explore neighbors in sorted order for deterministic tie-breaking behavior
        for next_airport in sorted(adj.get(curr, {}).keys()):
            # Enforce "no airport twice" constraint explicitly
            if next_airport in path:
                continue
            heapq.heappush(pq, (price + adj[curr][next_airport], stops + 1, path + [next_airport]))

    return None
