            has_dot = False
            while j < n and (expr[j].isdigit() or (expr[j] == '.' and not has_dot)):
                if expr[j] == '.':
                    has_dot = True
                j += 1
            tokens.append(('NUM', expr[i:j]))
            i = j
        elif i + 1 < n and expr[i:i+2] in ('**', '//'):
            tokens.append(('OP', expr[i:i+2]))
            i += 2
        elif c in '+-*/%()':
            if c == '(':
                tokens.append(('LPAREN', '('))
            elif c == ')':
                tokens.append(('RPAREN', ')'))
            else:
                tokens.append(('OP', c))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c}")
    tokens.append(('EOF', None))

    pos = [0]

    def peek():
        return tokens[pos[0]]

    def consume(expected_type=None):
        tok = tokens[pos[0]]
        if expected_type and tok[0] != expected_type:
            raise ValueError(f"Expected {expected_type}, got {tok[0]}")
        pos[0] += 1
        return tok

    def factor():
        tok = peek()
        if tok[0] == 'OP' and tok[1] in '+-':
            consume()
            operand = factor()
            return -operand if tok[1] == '-' else +operand
        return power()

    def power():
        left = atom()
        tok = peek()
        if tok[0] == 'OP' and tok[1] == '**':
            consume()
            right = factor()  # Right-associative via recursion/factor chain
            return left ** right
        return left

    def term():
        left = factor()
        while True:
            tok = peek()
            if tok[0] == 'OP' and tok[1] in {'*', '/', '//', '%'}:
                consume()
                right = factor()
                if tok[1] == '*':
                    left *= right
                elif tok[1] == '/':
                    left = left / right
                elif tok[1] == '//':
                    left = left // right
                else:
                    left = left % right
            else:
                break
        return left

    def expr():
        left = term()
        while True:
            tok = peek()
            if tok[0] == 'OP' and tok[1] in '+-':
                consume()
                right = term()
                if tok[1] == '+':
                    left += right
                else:
                    left -= right
            else:
                break
        return left

    def atom():
        tok = peek()
        if tok[0] == 'NUM':
            consume()
            val = tok[1]
            return float(val) if '.' in val else int(val)
        elif tok[0] == 'LPAREN':
            consume()
            res = expr()
            rparen = peek()
            if rparen[0] != 'RPAREN':
                raise ValueError("Missing closing parenthesis")
            consume('RPAREN')
            return res
        else:
            if tok[0] == 'EOF':
                raise ValueError("Unexpected end of input")
            if tok[0] == 'OP' and tok[1] in '+-*/%//**':
                raise ValueError(f"Unexpected operator '{tok[1]}'")
            if tok[0] == 'RPAREN':
                raise ValueError("Unbalanced parentheses")
            raise ValueError(f"Unexpected token: {tok}")

    result = expr()
    if pos[0] < len(tokens) - 1:
        raise ValueError("Unexpected tokens after expression")
    return result
