def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect every unique target (both keys and values)
    all_targets = set(deps.keys())
    for dep_list in deps.values():
        all_targets.update(dep_list)

    # Build adjacency list and compute in-degrees
    in_degree = {t: 0 for t in all_targets}
    adj = {t: [] for t in all_targets}

    for target, dependencies in deps.items():
        for dep in set(dependencies):  # Deduplicate allowed entries
            adj[dep].append(target)
            in_degree[target] += 1

    # Min-heap ensures lexicographically smallest choice at each step
    heap = [t for t in all_targets if in_degree[t] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    # If not all targets were processed, a cycle exists
    if len(result) != len(all_targets):
        raise ValueError("Dependency cycle detected")

