import time
from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock=time.monotonic):
        if capacity < 1 or ttl <= 0:
            raise ValueError("capacity must be >= 1 and ttl > 0")
        self._capacity = capacity
        self._ttl = ttl
        self._clock = clock
        self._cache = OrderedDict()

    def set(self, key, value) -> None:
        now = self._clock()
        expire = now + self._ttl
        self._cache.pop(key, None)
        self._cache[key] = [value, expire]

        # Evict expired entries and the LRU live entry if over capacity
        while len(self._cache) > self._capacity:
            _, evict_expire = self._cache.popitem(last=False)
            if evict_expire > now:
                break  # Found the LRU live entry to evict

    def get(self, key, default=None):
        if key not in self._cache:
            return default
        value, expire = self._cache[key]
        now = self._clock()

        if expire <= now:
            del self._cache[key]
            return default

        self._cache.move_to_end(key)  # Mark as MRU without resetting expiry
        return value

    def delete(self, key) -> bool:
        if key not in self._cache:
            return False
        _, expire = self._cache[key]
        now = self._clock()

        if expire <= now:
            del self._cache[key]
            return False  # Expired entries count as "none"

        del self._cache[key]
        return True

    def __len__(self):
        now = self._clock()
        return sum(1 for _, (_, exp) in self._cache.items() if exp > now)

    def __contains__(self, key) -> bool:
        if key not in self._cache:
            return False
        _, exp = self._cache[key]
        return exp > self._clock()
