                    i += 1
            else:
                current_field.append(char)
                i += 1
        else:
            # Only enter quoted mode at the very start of a field
            if not current_field and char == '"':
                in_quotes = True
                i += 1
            elif char == ',':
                fields.append("".join(current_field))
                current_field = []
                i += 1
            else:
                # Unquoted fields are taken literally until the next comma
                current_field.append(char)
                i += 1

    fields.append("".join(current_field))

    if in_quotes:
        raise ValueError("Unclosed quoted field")

    return fields
