import re

def expand_ranges(s: str) -> list[int]:
    if not s or not s.strip():
        return []
    result = []
    for item in s.split(','):
        item = item.strip()
        if not item:
            raise ValueError("Empty item")
        # Match single integer (including negative)
        if re.fullmatch(r'-?\d+', item):
            result.append(int(item))
        else:
            # Match range a-b, correctly handles negatives like -1-2 or -3--1
            m = re.fullmatch(r'(-?\d+)-(-?\d+)', item)
            if not m:
                raise ValueError("Malformed item")
            a, b = int(m.group(1)), int(m.group(2))
            if a > b:
                raise ValueError("Invalid range")
            result.extend(range(a, b + 1))
    return sorted(set(result))

def compress_ranges(nums) -> str:
    nums = sorted(set(nums))
    if not nums:
        return ""
    parts = []
    start = end = nums[0]
    for x in nums[1:]:
        if x == end + 1:
            end = x
        else:
            if end - start + 1 >= 3:
                parts.append(f"{start}-{end}")
            else:
                parts.extend(map(str, range(start, end + 1)))
            start = end = x
    # Process the final run
    if end - start + 1 >= 3:
        parts.append(f"{start}-{end}")
    else:
        parts.extend(map(str, range(start, end + 1)))
    return ",".join(parts)
